<template><div class="page"><div class="page-header"><div><el-button link @click="router.push('/agents')"><ArrowLeft />返回智能体中心</el-button><h1 class="page-title">{{workflow.business_name||'智能体工作流'}}</h1><p class="page-description">线程 {{workflow.thread_id}} · {{modeLabel(workflow.quality_mode)}}</p></div><div><el-button v-if="workflow.workflow_type==='KNOWLEDGE_CURATION'&&workflow.status==='AWAITING_REVIEW'" type="success" @click="confirmKnowledge">确认导入章节与知识点</el-button><el-button v-if="['FAILED','CANCELLED','INTERRUPTED'].includes(workflow.status)" type="primary" @click="retry">重试</el-button><el-button v-if="['WAITING','RUNNING'].includes(workflow.status)" type="danger" plain @click="cancel">取消</el-button></div></div>
<div class="status-board card"><div><StatusTag :value="workflow.status" /><h2>{{agentName(workflow.current_agent)}}</h2><p>{{statusCopy}}</p></div><div class="progress-ring"><el-progress type="circle" :percentage="workflow.progress||0" :width="112" :stroke-width="9" /></div></div>
<el-alert v-if="workflow.error_message" :title="workflow.error_message" type="error" show-icon :closable="false" style="margin:16px 0" />
<div class="trace-layout"><section class="card trace-card"><div class="card-header"><span class="card-title">协作时间线</span><span class="muted">{{workflow.steps?.length||0}} 个执行步骤</span></div><div class="trace-list"><article v-for="(step,index) in workflow.steps" :key="step.id" class="trace-step" :class="step.status.toLowerCase()"><div class="trace-marker"><span>{{index+1}}</span><i /></div><div class="trace-content"><div class="trace-head"><div><small>{{step.agent_name}}</small><h3>{{step.step_name}}</h3></div><StatusTag :value="step.status" /></div><div class="trace-facts"><span>第 {{step.attempt}} 次执行</span><span v-if="step.metrics?.duration_ms">用时 {{duration(step.metrics.duration_ms)}}</span><span>{{fmt(step.finished_at||step.started_at)}}</span></div><div v-if="step.output_summary&&Object.keys(step.output_summary).length" class="step-output"><b>输出摘要</b><pre>{{pretty(step.output_summary)}}</pre></div><el-alert v-if="step.error_message" :title="step.error_message" type="error" :closable="false" /></div></article><div v-if="!workflow.steps?.length" class="empty">工作流正在等待Worker领取。</div></div></section>
<aside><div class="card artifact-card"><div class="card-header"><span class="card-title">中间产物</span></div><el-collapse><el-collapse-item v-for="item in currentArtifacts" :key="item.id" :title="artifactLabel(item.artifact_type)"><div class="artifact-meta">{{agentName(item.created_by)}} · v{{item.version}}</div><pre>{{pretty(item.content)}}</pre></el-collapse-item></el-collapse><div v-if="!currentArtifacts.length" class="empty">暂无可查看产物。</div></div></aside></div></div></template>
<script setup>import{ref,computed,onMounted,onUnmounted}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{agentsApi}from'../../api';import StatusTag from'../../components/StatusTag.vue';const route=useRoute(),router=useRouter(),workflow=ref({}),agents=ref([]);let timer;const agentName=key=>agents.value.find(x=>x.key===key)?.name||key||'等待调度';const modeLabel=v=>({FAST:'快速模式',STANDARD:'标准模式',DEEP:'深度模式'}[v]||v);const statusCopy=computed(()=>({WAITING:'Worker将按优先级领取该任务。',RUNNING:'当前智能体正在处理，页面会自动更新。',AWAITING_REVIEW:'智能体协作已完成，正在等待教师确认。',SUCCESS:'工作流和人工确认已完成。',FAILED:'工作流未完成，请查看失败步骤和原因。'}[workflow.value.status]||'任务已停止。'));const currentArtifacts=computed(()=>(workflow.value.artifacts||[]).filter(x=>x.is_current));const pretty=v=>JSON.stringify(v,null,2);const duration=ms=>ms<1000?`${ms} ms`:`${(ms/1000).toFixed(1)} 秒`;const fmt=v=>v?new Date(v).toLocaleString():'-';const artifactLabel=v=>({EXECUTION_PLAN:'执行计划',EVIDENCE_PACK:'RAG 证据包',QUESTION_DRAFT:'题目草稿',REVIEW_REPORT:'答案校验报告',REVISION_REPORT:'修订报告',RULE_REPORT:'规则与去重报告',FINAL_REPORT:'最终质量报告',KNOWLEDGE_PREVIEW:'章节与知识点预览',PAPER_RULE:'组卷规则',VALIDATED_PAPER_RULE:'已校验组卷规则',PAPER_SELECTION_REPORT:'选题报告',PAPER_QUALITY_REPORT:'试卷质量报告'}[v]||v);const load=async()=>{workflow.value=await agentsApi.workflow(route.params.id);if(!['WAITING','RUNNING'].includes(workflow.value.status)&&timer){clearInterval(timer);timer=null}};const cancel=async()=>{await agentsApi.cancel(workflow.value.id);ElMessage.success('已提交取消请求');load()};const retry=async()=>{workflow.value=await agentsApi.retry(workflow.value.id);ElMessage.success('已重新加入队列');if(!timer)timer=setInterval(load,2000)};const confirmKnowledge=async()=>{await ElMessageBox.confirm('确认后会导入新章节和知识点，已有同名数据不会重复创建。','确认知识整理结果');const result=await agentsApi.confirm(workflow.value.id,{});ElMessage.success(`已导入 ${result.created_chapters} 个章节和 ${result.created_knowledge_points} 个知识点`);await load()};onMounted(async()=>{agents.value=await agentsApi.list();await load();timer=setInterval(load,2000)});onUnmounted(()=>timer&&clearInterval(timer));</script>
<style scoped>.status-board{display:flex;align-items:center;justify-content:space-between;padding:24px 28px;background:linear-gradient(120deg,#fff,#f4f9ff)}.status-board h2{margin:12px 0 3px;font-size:21px}.status-board p{margin:0;color:var(--text-secondary)}.trace-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(330px,.75fr);gap:18px;margin-top:18px}.trace-card,.artifact-card{overflow:hidden}.trace-list{padding:20px}.trace-step{display:grid;grid-template-columns:42px 1fr;gap:12px}.trace-marker{display:flex;flex-direction:column;align-items:center}.trace-marker span{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;color:#fff;background:#9ca8b8;font-weight:700}.trace-step.success .trace-marker span{background:var(--success)}.trace-step.running .trace-marker span{background:var(--primary);box-shadow:0 0 0 6px rgba(22,119,255,.09)}.trace-step.failed .trace-marker span{background:var(--danger)}.trace-marker i{width:1px;min-height:80px;flex:1;background:#dfe5ed}.trace-step:last-child .trace-marker i{background:linear-gradient(#dfe5ed,transparent)}.trace-content{padding-bottom:20px}.trace-head{display:flex;justify-content:space-between}.trace-head small{color:#0b8e8e;font-weight:700}.trace-head h3{margin:3px 0;font-size:16px}.trace-facts{display:flex;gap:16px;color:var(--text-secondary);font-size:11px}.step-output{margin-top:11px;padding:11px 13px;border-radius:8px;background:#f7f9fc}.step-output b{font-size:11px}.step-output pre,.artifact-card pre{margin:7px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace;color:#445066}.artifact-card :deep(.el-collapse){border:0}.artifact-card :deep(.el-collapse-item__header){padding:0 18px}.artifact-card :deep(.el-collapse-item__content){padding:0 18px 17px}.artifact-meta{color:var(--text-secondary);font-size:11px}@media(max-width:1280px){.trace-layout{grid-template-columns:1fr}}</style>
